#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, d;
    cin >> a >> b >> c >> d;

    long long maxSum = b + c;
    vector<long long> diff(maxSum + 2, 0);

    for (long long x = a; x <= b; ++x) {
        ++diff[x + b];
        --diff[x + c + 1];
    }

    for (long long s = 1; s <= maxSum; ++s)
        diff[s] += diff[s - 1];

    for (long long s = 1; s <= maxSum; ++s)
        diff[s] += diff[s - 1];

    long long totalPairs = (b - a + 1) * (c - b + 1);
    long long answer = 0;

    for (long long z = c; z <= d; ++z) {
        long long pairsAtMostZ = z >= maxSum ? totalPairs : diff[z];
        answer += totalPairs - pairsAtMostZ;
    }

    cout << answer << '\n';
    return 0;
}

